func classifyConvergence(steps []float64) string {
        if len(steps) <= 1 {
                return "converging"
        }
        decreasing := true
        increasing := true
        for i := 1; i < len(steps); i++ {
                if steps[i] >= steps[i-1] {
                        decreasing = false
                }
                if steps[i] <= steps[i-1] {
                        increasing = false
                }
        }
        if decreasing {
                return "converging"
        }
        if increasing {
                return "diverging"
        }
        return "oscillating"
}
