func float32Data(vals []float32) []byte {
        b := make([]byte, 4*len(vals))
        for i, v := range vals {
                binary.LittleEndian.PutUint32(b[4*i:4*i+4], math.Float32bits(v))
        }
        return b
}

func main() {
        // Tensor a: step changes are exactly equal (1, 1, 1) -> converging.
